// Step 1: Create a small Express server that issues two redirects
const express = require('express');
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
const fs = require('fs');

;(async () => {
  // 1) Start Express server with a redirect chain: /start → /middle → /end
  const app = express();
  app.get('/start', (req, res) => res.redirect(302, '/middle'));
  app.get('/middle', (req, res) => res.redirect(302, '/end'));
  app.get('/end', (req, res) => res.send('<!doctype html><html><body>Final page</body></html>'));

  const server = app.listen(0, async () => {
    const port = server.address().port;
    const url = `http://localhost:${port}/start`;

    // 2) Launch headless Chrome
    const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
    const options = {
      logLevel: 'info',
      output: 'html',
      onlyCategories: ['performance'],
      port: chrome.port,
    };

    // 3) Run Lighthouse on our redirect chain URL
    try {
      const runnerResult = await lighthouse(url, options);

      // 4) Save the HTML report to disk
      const htmlReport = runnerResult.report;
      const filePath = 'redirects-opportunity-bug.html';
      fs.writeFileSync(filePath, htmlReport);
      console.log(`Lighthouse report written to ${filePath}`);

      // Open the saved HTML in your browser to see the squished opportunity row.
    } catch (err) {
      console.error(err);
    } finally {
      await chrome.kill();
      server.close();
    }
  });
})();
